"""Replace Words — trie of roots, stop at the first complete root.

Time: O(total characters)   Space: O(total characters)
"""
from typing import List


class Solution:
    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        END = "$"
        trie = {}
        for root in dictionary:
            node = trie
            for ch in root:
                node = node.setdefault(ch, {})
            node[END] = True

        def shortest_root(word: str) -> str:
            node = trie
            for i, ch in enumerate(word):
                if ch not in node:
                    return word
                node = node[ch]
                if END in node:
                    return word[:i + 1]
            return word

        return " ".join(shortest_root(word) for word in sentence.split())
